// ============================================================================
// Shinzora · Edge Function `push`
// ----------------------------------------------------------------------------
// Sends a Web Push message for one stored notification row.
//
//   POST /functions/v1/push      { "notification_id": "<uuid>" }
//   x-push-key: <shared secret held in Supabase Vault>
//
// The caller is the database itself: migration 0038 installs a trigger that
// posts here after a `notifications` row is inserted. The trigger presents the
// secret generated by that migration, and `push_hook_ok()` — service_role only
// — is the only thing that can confirm it. A browser cannot call this function
// usefully: without the secret it is refused before it reads anything, and
// because the trigger holds the secret inside the database it never has to be
// copied into an environment variable.
//
// This function trusts nothing in the request body beyond the id — it re-reads
// the row, the member's preferences and their subscriptions with the service
// role, so a malformed payload cannot address somebody else's devices.
//
// What it will NOT do: report success it did not have. When VAPID keys are
// absent it answers 503 push_not_configured, and every skipped notification
// says why. The settings card reads that truth rather than guessing.
// ============================================================================

import webpush from "npm:web-push@3.6.7";
import { json, fail, preflight, readBody } from "../_shared/http.ts";
import { admin } from "../_shared/auth.ts";

const VAPID_PUBLIC = Deno.env.get("PUSH_VAPID_PUBLIC_KEY") ?? "";
const VAPID_PRIVATE = Deno.env.get("PUSH_VAPID_PRIVATE_KEY") ?? "";
const VAPID_SUBJECT = Deno.env.get("PUSH_VAPID_SUBJECT") ?? "mailto:official.shinzora@proton.me";
const SITE_URL = (Deno.env.get("SHINZORA_SITE_URL") ?? "https://shinzora.vercel.app").replace(/\/+$/, "");

const configured = Boolean(VAPID_PUBLIC && VAPID_PRIVATE);
if (configured) {
  try {
    webpush.setVapidDetails(VAPID_SUBJECT, VAPID_PUBLIC, VAPID_PRIVATE);
  } catch {
    /* setVapidDetails throws on a malformed key; `configured` stays true but
       every send will fail loudly below rather than silently. */
  }
}

type NotificationRow = {
  id: string;
  user_id: string;
  type: string | null;
  title: string | null;
  body: string | null;
  link: string | null;
  meta: Record<string, unknown> | null;
};

type SubscriptionRow = {
  id: string;
  endpoint: string;
  p256dh: string;
  auth: string;
};

Deno.serve(async (req) => {
  const options = preflight(req);
  if (options) return options;

  if (req.method !== "POST") return fail(405, "method_not_allowed", "Use POST.");

  /* verify_jwt is off for this function because the caller is Postgres, not a
     person; the shared secret is the authentication. An empty header is refused
     before anything is read. */
  const presented = (req.headers.get("x-push-key") ?? "").trim();
  if (!presented) return fail(401, "unauthorised", "This endpoint is called by the database only.");

  const db0 = admin();
  const { data: authorised, error: authError } = await db0.rpc("push_hook_ok", { p_secret: presented });
  if (authError) return fail(500, "hook_check_failed", authError.message);
  if (authorised !== true) return fail(401, "unauthorised", "This endpoint is called by the database only.");

  if (!configured) {
    return fail(
      503,
      "push_not_configured",
      "VAPID keys are not set for this function, so no push can be sent. In-app notices are unaffected."
    );
  }

  const body = await readBody<{ notification_id?: string }>(req);
  const notificationId = typeof body.notification_id === "string" ? body.notification_id.trim() : "";
  if (!notificationId) return fail(400, "missing_id", "notification_id is required.");

  const db = admin();

  const { data: row, error: rowError } = await db
    .from("notifications")
    .select("id,user_id,type,title,body,link,meta")
    .eq("id", notificationId)
    .maybeSingle<NotificationRow>();

  if (rowError) return fail(500, "lookup_failed", rowError.message);
  if (!row) return fail(404, "not_found", "That notification no longer exists.");

  /* ---------------------------------------------------------------- prefs */
  const { data: prefs } = await db
    .from("notification_preferences")
    .select("group_messages,group_mentions,push_enabled")
    .eq("user_id", row.user_id)
    .maybeSingle<{ group_messages: boolean; group_mentions: boolean; push_enabled: boolean }>();

  if (prefs && prefs.push_enabled === false) {
    return json({ ok: true, sent: 0, skipped: "push_disabled" });
  }

  const meta = (row.meta ?? {}) as Record<string, unknown>;
  const groupId = typeof meta.groupId === "string" ? meta.groupId : null;
  const kind = typeof meta.kind === "string" ? meta.kind : "";
  const isMention = kind === "mention" || kind === "everyone";

  if (groupId) {
    if (isMention && prefs && prefs.group_mentions === false) {
      return json({ ok: true, sent: 0, skipped: "mentions_off" });
    }
    if (!isMention && prefs && prefs.group_messages === false) {
      return json({ ok: true, sent: 0, skipped: "group_messages_off" });
    }
    /* A muted group still delivers mentions the member asked for — muting
       silences chatter, not a direct call-out. */
    const { data: membership } = await db
      .from("community_group_members")
      .select("muted")
      .eq("group_id", groupId)
      .eq("user_id", row.user_id)
      .maybeSingle<{ muted: boolean }>();
    if (membership?.muted && !isMention) {
      return json({ ok: true, sent: 0, skipped: "group_muted" });
    }
  }

  /* --------------------------------------------------------- subscriptions */
  const { data: subscriptions, error: subError } = await db
    .from("push_subscriptions")
    .select("id,endpoint,p256dh,auth")
    .eq("user_id", row.user_id)
    .is("disabled_at", null);

  if (subError) return fail(500, "subscriptions_failed", subError.message);
  const devices = (subscriptions ?? []) as SubscriptionRow[];
  if (!devices.length) return json({ ok: true, sent: 0, skipped: "no_devices" });

  const link = row.link && row.link.startsWith("/") ? `${SITE_URL}${row.link}` : row.link || `${SITE_URL}/app/?view=messages&tab=groups`;
  const payload = JSON.stringify({
    title: row.title || "Shinzora",
    body: row.body || "You have a new message.",
    url: link,
    groupId,
    messageId: typeof meta.messageId === "string" ? meta.messageId : null,
    groupName: typeof meta.groupName === "string" ? meta.groupName : null,
    senderName: typeof meta.senderName === "string" ? meta.senderName : null,
    kind: kind || "message"
  });

  let sent = 0;
  const failures: { endpoint: string; status: number }[] = [];

  await Promise.all(
    devices.map(async (device) => {
      try {
        await webpush.sendNotification(
          { endpoint: device.endpoint, keys: { p256dh: device.p256dh, auth: device.auth } },
          payload,
          { TTL: 60 * 60 * 12, urgency: isMention ? "high" : "normal" }
        );
        sent += 1;
        await db.rpc("push_mark_result", { p_endpoint: device.endpoint, p_status: 200 });
      } catch (error) {
        const status = Number((error as { statusCode?: number })?.statusCode ?? 0);
        failures.push({ endpoint: device.endpoint, status });
        /* 404/410 means the push service has retired this endpoint; the RPC
           disables it so we stop retrying a device that no longer exists. */
        try {
          await db.rpc("push_mark_result", { p_endpoint: device.endpoint, p_status: status || 0 });
        } catch {
          /* The send already failed; a bookkeeping failure must not 500. */
        }
      }
    })
  );

  return json({
    ok: true,
    sent,
    devices: devices.length,
    failed: failures.length,
    note: failures.length ? "Some devices were unreachable; see push_subscriptions.failures." : undefined
  });
});
